package com.bank.storage;

import java.util.*;
import java.util.logging.*;

public class StorageDemo {
    private static final Logger log = Logger.getLogger("Storage");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FileStorageService storage = new FileStorageService();

        // Rajesh uploads a loan agreement (readable by himself + officer)
        byte[] loanDoc = "LOAN AGREEMENT PAGE1...PAGE2...PAGE3".repeat(100).getBytes();
        String fileId = storage.upload("loan-SAV2001", "SAV2001", loanDoc,
            Set.of("SAV2001", "OFFICER-9"));
        log.info(() -> "Uploaded fileId=" + fileId);

        // Same standard T&C PDF uploaded twice → chunks deduplicated
        byte[] terms = "STANDARD TERMS AND CONDITIONS".repeat(200).getBytes();
        storage.upload("terms-A", "SAV2001", terms, Set.of("SAV2001"));
        storage.upload("terms-B", "CUR3001", terms, Set.of("CUR3001"));
        log.info(() -> "Total unique chunks stored: " + storage.uniqueChunkCount());

        // Access control: Priya (not a reader) tries to download the loan doc
        try {
            storage.download("loan-SAV2001", 1, "CUR3001");
        } catch (SecurityException e) {
            log.warning(() -> "Access denied as expected: " + e.getMessage());
        }

        // Authorized download by Rajesh
        byte[] got = storage.download("loan-SAV2001", 1, "SAV2001");
        log.info(() -> "Rajesh downloaded " + got.length + " bytes (v1)");

        // New version replaces a page
        byte[] loanV2 = "LOAN AGREEMENT PAGE1...PAGE2b...PAGE3".repeat(100).getBytes();
        storage.upload("loan-SAV2001", "SAV2001", loanV2, Set.of("SAV2001", "OFFICER-9"));
        log.info(() -> "Versions of loan doc: " + storage.versions("loan-SAV2001"));
    }
}

