package com.bank.storage;

import java.security.*;
import java.util.*;

public class Chunker {
    public static final int CHUNK_SIZE = 4096; // 4 KB for the demo

    public List<byte[]> split(byte[] file) {
        List<byte[]> chunks = new ArrayList<>();
        for (int off = 0; off < file.length; off += CHUNK_SIZE)
            chunks.add(Arrays.copyOfRange(file, off, Math.min(off + CHUNK_SIZE, file.length)));
        return chunks;
    }
    public String hash(byte[] data) {
        try {
            byte[] d = MessageDigest.getInstance("SHA-256").digest(data);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) sb.append(String.format("%02x", d[i]));
            return sb.toString();
        } catch (NoSuchAlgorithmException e) { throw new RuntimeException(e); }
    }
}
