package com.bank.storage;

import java.util.*;
import java.util.logging.*;

// Content-addressed blob store: key = chunk hash. Dedup is automatic.
public class BlobStore {
    private static final Logger log = Logger.getLogger("Storage");
    private final Map<String, byte[]> blobs = new HashMap<>();

    public void putIfAbsent(String hash, byte[] data) {
        if (blobs.containsKey(hash)) {
            log.fine(() -> "dedup: chunk " + hash + " already stored");
            return;   // deduplicated
        }
        blobs.put(hash, data);
    }
    public byte[] get(String hash) { return blobs.get(hash); }
    public int size() { return blobs.size(); }
}
