package com.bank.storage;

import java.util.*;

public class FileMetadata {
    private final String fileId;
    private final String owner;
    private final long version;
    private final List<String> chunkHashes;
    private final Set<String> readers;

    public FileMetadata(String fileId, String owner, long version,
                        List<String> chunkHashes, Set<String> readers) {
        this.fileId = fileId; this.owner = owner; this.version = version;
        this.chunkHashes = chunkHashes; this.readers = readers;
    }
    public String getOwner() { return owner; }
    public long getVersion() { return version; }
    public List<String> getChunkHashes() { return chunkHashes; }
    public boolean canRead(String user) { return owner.equals(user) || readers.contains(user); }
}
