package com.bank.storage;

import java.util.*;

public class MetadataStore {
    // fileId -> version -> metadata
    private final Map<String, NavigableMap<Long, FileMetadata>> byFile = new HashMap<>();

    public long nextVersion(String fileId) {
        var versions = byFile.get(fileId);
        return versions == null ? 1 : versions.lastKey() + 1;
    }
    public void save(String fileId, FileMetadata m) {
        byFile.computeIfAbsent(fileId, k -> new TreeMap<>()).put(m.getVersion(), m);
    }
    public FileMetadata get(String fileId, long version) {
        var versions = byFile.get(fileId);
        return versions == null ? null : versions.get(version);
    }
    public List<Long> versions(String fileId) {
        var versions = byFile.get(fileId);
        return versions == null ? List.of() : new ArrayList<>(versions.keySet());
    }
}
